changeSet.sql:
do $$
begin
  -- Do not remove legacy uniqueness unless the replacement tenant
  -- uniqueness guarantee is installed and the expected index exists.
  if to_regclass('uq_eic_active_per_tenant') is null then
    raise exception 'R1B migration requires uq_eic_active_per_tenant (034)';
  end if;
  if to_regclass('uq_eic_active_binding') is null then
    raise exception 'Expected legacy ACTIVE issuer index is missing';
  end if;
  if exists (
    select 1 from enterprise_identity_connections
    where status='ACTIVE'
    group by tenant_id
    having count(*) > 1
  ) then
    raise exception 'Multiple ACTIVE connections per tenant block R1B migration';
  end if;
  drop index uq_eic_active_binding;
end $$;

rollback.sql:
do $$
begin
  if exists (
    select 1 from enterprise_identity_connections
    where status='ACTIVE'
    group by provider_id, issuer_uri, api_audience
    having count(*) > 1
  ) then
    raise exception 'Cannot restore legacy ACTIVE binding uniqueness while shared-issuer bindings exist';
  end if;
end $;

create unique index uq_eic_active_binding
on enterprise_identity_connections(provider_id, issuer_uri, api_audience)
where status='ACTIVE';
